import sys

def main():
    input_stream = sys.stdin
    output_stream = sys.stdout
    for line in input_stream:
        if not line.strip():
            continue
        parts = line.strip().split()
        if len(parts) < 2:
            continue
        n = int(parts[0])
        s = parts[1]
        ok = False
        one = 0
        tt = ""
        twoans = ""
        wordnok = True
        for c in range(n):
            ch = s[c]
            if ch == '(':
                ok = True
                wordnok = True
                tt = ""
            elif ch == ')':
                tt = ""
                ok = False
            else:
                if not ok:
                    if ch == '_':
                        tt = ""
                    else:
                        tt += ch
                    if len(tt) > len(twoans):
                        twoans = tt
                else:
                    if ch == '_':
                        wordnok = True
                    else:
                        if wordnok:
                            one += 1
                            wordnok = False
        output_stream.write(str(len(twoans)) + " " + str(one) + "\n")

if __name__ == "__main__":
    main()

